using System; using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using Microsoft.IdentityModel.Tokens; class Program { static void Main() { var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes("AGRIRENT_SUPER_SECRET_JWT_KEY_2025_1234567890")); var creds = new SigningCredentials(key, SecurityAlgorithms.HmacSha256); var claims = new[] { new Claim(ClaimTypes.NameIdentifier, "1") }; var token = new JwtSecurityToken(issuer: "AgriRentAPI", audience: "AgriRentUsers", claims: claims, expires: DateTime.Now.AddDays(1), signingCredentials: creds); Console.WriteLine(new JwtSecurityTokenHandler().WriteToken(token)); } }